import { test, expect } from '@playwright/test';

test.describe('Character Count Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display character count for textarea', async ({ page }) => {
    const textarea = page.getByRole('textbox', { name: /your textarea label/i });
    await textarea.fill('This is a test input to check character count.');

    const characterCount = page.getByText(/character count/i);
    await expect(characterCount).toHaveText('Character count: 38'); // Adjust based on input length
  });

  test('should not allow more than 500 characters', async ({ page }) => {
    const textarea = page.getByRole('textbox', { name: /your textarea label/i });
    const longText = 'A'.repeat(501);
    await textarea.fill(longText);

    const characterCount = page.getByText(/character count/i);
    await expect(characterCount).toHaveText('Character count: 500'); // Ensure it caps at 500
    await expect(textarea).toHaveValue(longText.slice(0, 500)); // Ensure textarea value is capped
  });
});
